import java.util.Scanner;

public class Main {
    public static int readInt(Scanner sc) {
        int num = 0;
        while (true) {
            if (!sc.hasNext()) break;
            String token = sc.next();
            if (token.matches("\\d+")) {
                num = Integer.parseInt(token);
                break;
            }
        }
        return num;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        StringBuilder result = new StringBuilder();
        result.append(s.charAt(0));
        boolean atFlag = false;
        int length = s.length();

        StringBuilder sBuilder = new StringBuilder(s);
        sBuilder.append("\u0001\u0001\u0001\u0001");
        String sExtended = sBuilder.toString();

        int i = 1;
        while (i < length) {
            if (i + 3 < sExtended.length() && sExtended.charAt(i) == 'd' && sExtended.charAt(i + 1) == 'o' && sExtended.charAt(i + 2) == 't' && sExtended.charAt(i + 3) != '\u0001') {
                result.append('.');
                i += 3;
            } else if (i + 1 < sExtended.length() && sExtended.charAt(i) == 'a' && sExtended.charAt(i + 1) == 't' && !atFlag) {
                result.append('@');
                atFlag = true;
                i += 2;
            } else {
                result.append(sExtended.charAt(i));
                i++;
            }
        }
        System.out.print(result.toString());
        sc.close();
    }
}
